// Synergy Harness — автономный ИИ-агент на чистом Go.
// Аналог OpenClaw / Hermes-agent: OpenAI-compatible API, веб-поиск, тулы, TUI.
//
// Сборка:   go build -o synergy-harness .
// Запуск:   OPENAI_API_KEY=sk-... ./synergy-harness           (TUI-режим)
//
//	./synergy-harness -oneshot "найди цену биткоина"  (один запрос без TUI)
//
// Переменные окружения:
//
//	OPENAI_API_KEY   — ключ (обязательно)
//	OPENAI_BASE_URL  — базовый URL, по умолчанию https://api.openai.com/v1
//	                   (подходит любой OpenAI-compatible: OpenRouter, Groq, Ollama, vLLM, LM Studio)
//	GOMNI_MODEL      — модель, по умолчанию gpt-4o-mini
//	GOMNI_WORKDIR    — рабочая директория тулов, по умолчанию текущая
package main

import (
	"bufio"
	"bytes"
	"context"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	mrand "math/rand"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"
	"unicode/utf8"
	"unsafe"
)

// ============================================================================
// ГЛАВА 1. УТИЛИТЫ И ЦВЕТА
// ============================================================================

var startTime = time.Now()

func getenv(key, def string) string {
	if v := strings.TrimSpace(os.Getenv(key)); v != "" {
		return v
	}
	// совместимость: GOMNI_* -> SYNERGY_*
	if strings.HasPrefix(key, "GOMNI_") {
		if v := strings.TrimSpace(os.Getenv("SYNERGY_" + strings.TrimPrefix(key, "GOMNI_"))); v != "" {
			return v
		}
	}
	return def
}

func trunc(s string, n int) string {
	if utf8.RuneCountInString(s) <= n {
		return s
	}
	r := []rune(s)
	return string(r[:n]) + "…"
}

func clampStr(s string, max int) string {
	if len(s) <= max {
		return s
	}
	return s[:max] + fmt.Sprintf("\n[...обрезано, всего %d байт]", len(s))
}

func mustJSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return "{}"
	}
	return string(b)
}

// ANSI-цвета
const (
	cReset  = "\033[0m"
	cBold   = "\033[1m"
	cDim    = "\033[2m"
	cItalic = "\033[3m"
	cRed    = "\033[31m"
	cGreen  = "\033[32m"
	cYellow = "\033[33m"
	cBlue   = "\033[34m"
	cPurple = "\033[35m"
	cCyan   = "\033[36m"
	cGray   = "\033[90m"
	cBGBlue = "\033[44m"
)

func col(c, s string) string { return c + s + cReset }

// ============================================================================
// TLS: КОРНИ ДОВЕРИЯ, ВШИТЫЕ В БИНАРЬ
// ============================================================================
//
// Статичные бинари (linux/arm, android) в Termux/контейнерах не видят
// системный CA-стор, из-за чего x509 падает с "certificate signed by unknown
// authority". Решение: вшиваем бандл CA (cacert.pem, curl.se/ca) и добавляем
// его к системным корням. SSL_CERT_FILE=<path> — свой файл; -insecure —
// отключить проверку ТОЛЬКО по явному флагу (по умолчанию — никогда).

