// ============================================================================
// ГЛАВА 6. МИНИ-КАЛЬКУЛЯТОР (рекурсивный спуск, без внешних либ)
// ============================================================================

type exprParser struct {
	s   string
	pos int
}

func evalExpr(s string) (float64, error) {
	p := &exprParser{s: s}
	v, err := p.parseExpr()
	if err != nil {
		return 0, err
	}
	p.skipWS()
	if p.pos != len(p.s) {
		return 0, fmt.Errorf("лишние символы на позиции %d", p.pos)
	}
	return v, nil
}

func (p *exprParser) skipWS() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t') {
		p.pos++
	}
}

func (p *exprParser) parseExpr() (float64, error) { // + -
	v, err := p.parseTerm()
	if err != nil {
		return 0, err
	}
	for {
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == '+' {
			p.pos++
			r, err := p.parseTerm()
			if err != nil {
				return 0, err
			}
			v += r
		} else if p.pos < len(p.s) && p.s[p.pos] == '-' {
			p.pos++
			r, err := p.parseTerm()
			if err != nil {
				return 0, err
			}
			v -= r
		} else {
			return v, nil
		}
	}
}

func (p *exprParser) parseTerm() (float64, error) { // * / %
	v, err := p.parsePow()
	if err != nil {
		return 0, err
	}
	for {
		p.skipWS()
		if p.pos >= len(p.s) {
			return v, nil
		}
		op := p.s[p.pos]
		if op != '*' && op != '/' && op != '%' {
			return v, nil
		}
		p.pos++
		r, err := p.parsePow()
		if err != nil {
			return 0, err
		}
		switch op {
		case '*':
			v *= r
		case '/':
			if r == 0 {
				return 0, errors.New("деление на ноль")
			}
			v /= r
		case '%':
			if r == 0 {
				return 0, errors.New("деление на ноль")
			}
			v = float64(int64(v) % int64(r))
		}
	}
}

func (p *exprParser) parsePow() (float64, error) { // ^
	v, err := p.parseUnary()
	if err != nil {
		return 0, err
	}
	p.skipWS()
	if p.pos < len(p.s) && p.s[p.pos] == '^' {
		p.pos++
		r, err := p.parsePow()
		if err != nil {
			return 0, err
		}
		v = powf(v, r)
	}
	return v, nil
}

func powf(a, b float64) float64 {
	if b == 0 {
		return 1
	}
	if b == float64(int64(b)) && b > 0 && b < 64 {
		res := 1.0
		for i := int64(0); i < int64(b); i++ {
			res *= a
		}
		return res
	}
	// общий случай: a^b = e^(b*ln a)
	if a <= 0 {
		return 0
	}
	return expf(b * lnf(a))
}

func lnf(x float64) float64 {
	// ln через ряд atanh: ln x = 2*atanh((x-1)/(x+1))
	if x <= 0 {
		return 0
	}
	k := 0
	for x > 2 {
		x /= 2
		k++
	}
	for x < 0.5 {
		x *= 2
		k--
	}
	z := (x - 1) / (x + 1)
	z2 := z * z
	sum := 0.0
	term := z
	for i := 1; i < 40; i += 2 {
		sum += term / float64(i)
		term *= z2
	}
	return 2*sum + float64(k)*0.6931471805599453
}

func expf(x float64) float64 {
	// e^x через разложение e^x = 2^k * e^r
	k := int(x / 0.6931471805599453)
	r := x - float64(k)*0.6931471805599453
	sum, term := 1.0, 1.0
	for i := 1; i < 30; i++ {
		term *= r / float64(i)
		sum += term
	}
	return sum * powf(2, float64(k))
}

func sqrtf(x float64) float64 {
	if x <= 0 {
		return 0
	}
	g := x
	for i := 0; i < 60; i++ {
		g = (g + x/g) / 2
	}
	return g
}

func (p *exprParser) parseUnary() (float64, error) {
	p.skipWS()
	if p.pos < len(p.s) && p.s[p.pos] == '-' {
		p.pos++
		v, err := p.parseUnary()
		return -v, err
	}
	if p.pos < len(p.s) && p.s[p.pos] == '+' {
		p.pos++
		return p.parseUnary()
	}
	return p.parseAtom()
}

func (p *exprParser) parseAtom() (float64, error) {
	p.skipWS()
	if p.pos >= len(p.s) {
		return 0, errors.New("неожиданный конец выражения")
	}
	if p.s[p.pos] == '(' {
		p.pos++
		v, err := p.parseExpr()
		if err != nil {
			return 0, err
		}
		p.skipWS()
		if p.pos >= len(p.s) || p.s[p.pos] != ')' {
			return 0, errors.New("нет закрывающей скобки")
		}
		p.pos++
		return v, nil
	}
	// функции
	if p.pos < len(p.s) && isAlpha(p.s[p.pos]) {
		start := p.pos
		for p.pos < len(p.s) && isAlpha(p.s[p.pos]) {
			p.pos++
		}
		name := p.s[start:p.pos]
		p.skipWS()
		if p.pos >= len(p.s) || p.s[p.pos] != '(' {
			return 0, fmt.Errorf("после %s ожидается (", name)
		}
		p.pos++
		a, err := p.parseExpr()
		if err != nil {
			return 0, err
		}
		var b2 float64
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == ',' {
			p.pos++
			b2, err = p.parseExpr()
			if err != nil {
				return 0, err
			}
		}
		p.skipWS()
		if p.pos >= len(p.s) || p.s[p.pos] != ')' {
			return 0, fmt.Errorf("после %s нет )", name)
		}
		p.pos++
		switch name {
		case "sqrt":
			return sqrtf(a), nil
		case "abs":
			if a < 0 {
				return -a, nil
			}
			return a, nil
		case "min":
			if a < b2 {
				return a, nil
			}
			return b2, nil
		case "max":
			if a > b2 {
				return a, nil
			}
			return b2, nil
		case "pow":
			return powf(a, b2), nil
		}
		return 0, fmt.Errorf("неизвестная функция %s", name)
	}
	// число
	start := p.pos
	for p.pos < len(p.s) && (isDigit(p.s[p.pos]) || p.s[p.pos] == '.') {
		p.pos++
	}
	if start == p.pos {
		return 0, fmt.Errorf("ожидалось число на позиции %d", p.pos)
	}
	return strconv.ParseFloat(p.s[start:p.pos], 64)
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }
func isAlpha(c byte) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') }

// ============================================================================
// ГЛАВА 7. АГЕНТ-ЦИКЛ (reason -> act -> observe)
// ============================================================================

const systemPrompt = `Ты — Synergy Harness, автономный ИИ-агент. Отвечай на языке пользователя.

СРЕДА ВЫПОЛНЕНИЯ (универсально):
- Ты можешь работать и на десктопе (Linux/macOS/Windows), и на Android в Termux. Не предполагай конкретную ОС: пути, shell и доступные утилиты каждый раз уточняй через факты (list_dir, run_shell uname -a / pwd), а не по умолчанию.
- В Termux: нет systemd/sudo, домашняя папка ~ = $HOME, пакеты ставятся через pkg; обращения к системе Android — только через штатные тулы (termux-api, если он есть). На десктопе те же действия делай штатными средствами ОС. Перед вызовом платформенно-зависимой команды проверь её наличие (command -v / which) и имей запасной вариант.
- Изолированный sandbox_run доступен на обеих платформах — недоверенный код запускай там, это всегда безопасно.

ДИСЦИПЛИНА ФАКТОВ (критично):
1. Никогда не выдумывай URL, числа, даты, цитаты и состояние системы. Факты — только из выдачи тулов или из слов пользователя. Данных нет — честно скажи «не знаю» и предложи, как проверить.
2. Утверждая факт из интернета, ссылайся только на URL, которые реально вернули web_search / web_fetch в этом диалоге.

РАБОТА С ТУЛАМИ:
3. Свежая информация, факты, новости, погода, курсы → web_search, затем web_fetch для чтения источника. Если тул упал (сеть, лимит) — попробуй другой подход или альтернативный сервис, прежде чем сдаваться.
4. Файлы: read_file / write_file / edit_file / list_dir. Недоверенный или экспериментальный код запускай в sandbox_run (изолированный userspace-сандбокс), доверенные системные команды — в run_shell.
5. Вычисления — calculator. Время — get_time. Независимую объёмную подзадачу (исследование, проверка фактов, черновик) поручай субагенту через delegate.

АВТОНОМНОСТЬ:
6. Действуй сам: вызывай тулы подряд, пока задача не решена. Не спрашивай разрешения на безопасные действия и не извиняйся повторно за сбой — чини и иди дальше.
7. Цикл завершай финальным ответом: структурированно, по делу, источники — ссылками. Не заканчивай ответ вопросом, если можешь просто сделать следующий шаг.

ПАМЯТЬ:
8. Важные факты о пользователе, проекте и принятые решения сохраняй через remember. Перед ответом, опирающимся на прошлый опыт, загляни в recall.

SELF-REPAIR / РАСШИРЕНИЕ СЕБЯ:
9. Если для задачи не хватает тула (нужен API, парсер, интеграция) — НЕ сдавайся: создай его сам через write_plugin и сразу пользуйся. Протокол плагина описан в описании тула write_plugin.
10. Если write_plugin вернул ошибку handshake — прочитай её, исправь скрипт и запиши заново. Итерируй, пока плагин не подключится.

ТАСКИ (обязательная дисциплина, лимит — 2 активных таска на сессию):
11. На любую нетривиальную задачу (больше одного шага) СНАЧАЛА открой таск тулом task_open с коротким названием того, что делаешь. Тасков одновременно открыто не больше двух: закончил один — сразу закрой его task_close и только потом открывай следующий.
12. Каждое крупное действие помечай в ответе тегом таска: [task #N] перед описанием шага. Завершив таск, вызови task_close и явно уведомь пользователя: «таск #N закрыт: <что сделано>». Не оставляй таски висеть открытыми в конце ответа.`

// AgentEvent — событие агента для отображения в UI.
type AgentEvent struct {
	Kind    string // "think" | "tool_call" | "tool_result" | "answer" | "error" | "info"
	Title   string
	Body    string
	Elapsed time.Duration
}

type Agent struct {
	LLM           *LLMClient
	Tools         []Tool
	ToolIndex     map[string]int
	Messages      []Message
	MaxSteps      int
	OnEvent       func(AgentEvent)
	StreamUI      bool // печатать ли текст ответа потоково в onDelta
	TotalTok      int
	Workdir       string
	pendingImages []string // data-URL картинки для следующего user-сообщения (vision)
	// Steer — мягкая подмешивка инструкций без остановки агента (аналог /steer у Hermes):
	// сообщения из канала вставляются в контекст между шагами, агент продолжает работу.
	Steer chan string
	Turn  int // текущий ход диалога (user-сообщений обработано)
	Todos []TodoItem
}

// TodoItem — пункт плана агента (тул todo_write обновляет список; на больших экранах TUI показывает панель).
type TodoItem struct {
	Text   string `json:"text"`
	Status string `json:"status"` // pending | doing | done
}

// SteerMsg мягко подмешивает инструкцию в контекст (вызывается между шагами агента).
func (a *Agent) drainSteer() {
	if a.Steer == nil {
		return
	}
	for {
		select {
		case s, ok := <-a.Steer:
			if !ok {
				return
			}
			s = strings.TrimSpace(s)
			if s == "" {
				continue
			}
			a.Messages = append(a.Messages, Message{Role: "user", Content: "[STEER от пользователя, не прерывая текущую задачу учти и продолжай]: " + s})
			a.emit("info", "steer", "принято: "+s, 0)
		default:
			return
		}
	}
}

// ContextStatus — заполненность контекста для статус-бара (chars, примерный % окна).
func (a *Agent) ContextStatus() (int, int) {
	n := 0
	for _, m := range a.Messages {
		n += len(m.Content)
		for _, tc := range m.ToolCalls {
			n += len(tc.Function.Arguments)
		}
	}
	capChars := envInt("GOMNI_COMPACT_CHARS", a.modelContextChars()*9/10)
	if capChars <= 0 {
		capChars = 90000
	}
	pct := n * 100 / capChars
	if pct > 100 {
		pct = 100
	}
	return n, pct
}

func NewAgent(llm *LLMClient, workdir string, plugins ...*Plugin) *Agent {
	tools := BuildTools(workdir)
	idx := map[string]int{}
	for i, t := range tools {
		idx[t.Spec.Function.Name] = i
	}
	a := &Agent{
		LLM:       llm,
		Tools:     tools,
		ToolIndex: idx,
		MaxSteps:  25,
		Steer:     make(chan string, 16),
		Workdir:   workdir,
	}
	a.registerRuntimeTools(workdir) // delegate (субагенты)
	a.registerSelfRepair(workdir)   // write_plugin (самописание плагинов)
	// Регистрируем тулы плагинов
	for _, p := range plugins {
		for _, t := range p.Tools {
			a.RegisterTool(t.Spec, t.Handler)
		}
	}
	// Подмешиваем workspace (SOUL.md/AGENT.md) и память в системный промпт
	sys := systemPrompt + workspaceContext(workdir)
	if mem, err := os.ReadFile(filepath.Join(workdir, ".synergy_memory.md")); err == nil && len(mem) > 0 {
		sys += "\n\nТвоя долговременная память:\n" + clampStr(string(mem), 4000)
	}
	if len(plugins) > 0 {
		names := make([]string, 0, len(plugins))
		for _, p := range plugins {
			names = append(names, p.Name)
		}
		sys += "\n\nПодключённые плагины: " + strings.Join(names, ", ") + " — их тулы доступны наравне со встроенными."
	}
	sys += "\n\nРабота с задачами: для любой многошаговой задачи СНАЧАЛА вызови todo_write со списком шагов, по ходу помечай doing/done. Когда задача полностью завершена — вызови send_notification с кратким итогом (что сделано, где результат)."
	sys += "\n\nСаморазвитие: мануал по созданию плагинов лежит в файле PLUGINS.md твоего workspace (не встроен сюда). Если пользователь просит возможность, которой нет среди твоих тулов, — прочитай " + filepath.Join(workdir, ".gomni", "PLUGINS.md") + " через read_file и напиши себе плагин тулом write_plugin, затем пользуйся им."
	a.Messages = []Message{{Role: "system", Content: sys}}
	return a
}

// RegisterTool — добавляет тул (в т.ч. из плагина) в агента. Дубликаты имён игнорируются.
func (a *Agent) RegisterTool(spec ToolSpec, handler func(ctx context.Context, args map[string]any) (string, error)) {
	if _, exists := a.ToolIndex[spec.Function.Name]; exists {
		return
	}
	a.Tools = append(a.Tools, Tool{Spec: spec, Handler: handler})
	a.ToolIndex[spec.Function.Name] = len(a.Tools) - 1
}

func (a *Agent) emit(kind, title, body string, d time.Duration) {
	if a.OnEvent != nil {
		a.OnEvent(AgentEvent{Kind: kind, Title: title, Body: body, Elapsed: d})
	}
}

// Run — запускает агент-цикл по пользовательскому запросу. Возвращает финальный ответ.
func (a *Agent) Run(ctx context.Context, userInput string) (string, error) {
	msg := Message{Role: "user", Content: userInput, Images: a.pendingImages}
	a.pendingImages = nil // одноразовые: прикрепления уходят с первым сообщением
	a.Messages = append(a.Messages, msg)
	a.Turn++
	a.emit("turn", "", strconv.Itoa(a.Turn), 0)
	a.maybeCompact(ctx) // автосжатие разросшегося контекста (сабагент-суммаризатор)

	specs := make([]ToolSpec, len(a.Tools))
	for i, t := range a.Tools {
		specs[i] = t.Spec
	}
	var loopSigs []string        // сигнатуры вызовов для детекции циклов
	sources := map[string]bool{} // URL'ы, реально вернувшиеся из тулов (анти-галлюцинации)

	for step := 0; step < a.MaxSteps; step++ {
		a.drainSteer() // мягкие инструкции пользователя, не прерывая работу
		start := time.Now()
		req := ChatRequest{Messages: a.Messages, Tools: specs}

		var content string
		var toolCalls []ToolCall

		if a.StreamUI {
			res, err := a.LLM.CompleteStream(ctx, req, func(delta string) {
				a.emit("delta", "", delta, 0)
			})
			if err != nil {
				return "", err
			}
			content, toolCalls = res.Content, res.ToolCalls
		} else {
			resp, err := a.LLM.Complete(ctx, req)
			if err != nil {
				return "", err
			}
			a.TotalTok += resp.Usage.TotalTokens
			content = resp.Choices[0].Message.Content
			toolCalls = resp.Choices[0].Message.ToolCalls
		}
		d := time.Since(start)

		// Нет вызовов тулов — финальный ответ
		if len(toolCalls) == 0 {
			content = checkHallucinations(content, sources)
			a.Messages = append(a.Messages, Message{Role: "assistant", Content: content})
			if !a.StreamUI {
				a.emit("answer", "Ответ", content, d)
			} else {
				a.emit("answer_done", "", "", d)
			}
			return content, nil
		}

		// Есть вызовы тулов — выполняем
		a.Messages = append(a.Messages, Message{Role: "assistant", Content: content, ToolCalls: toolCalls})
		if content != "" {
			a.emit("think", "Рассуждение", content, d)
		}
		for _, tc := range toolCalls {
			name := tc.Function.Name
			a.emit("tool_call", name, tc.Function.Arguments, 0)

			// Анти-цикл: детекция повторяющихся вызовов с одинаковыми аргументами
			sig := name + "|" + tc.Function.Arguments
			repCount := 0
			for _, s := range loopSigs {
				if s == sig {
					repCount++
				}
			}
			if repCount >= 3 {
				a.emit("info", "anti-loop", "обнаружен цикл: "+name+" вызван 3+ раза с теми же аргументами — стоп", 0)
				a.Messages = append(a.Messages, Message{Role: "tool", ToolCallID: tc.ID, Name: name,
					Content: "СТОП: ты вызвал этот тул 3+ раза с теми же аргументами. Смени стратегию или дай финальный ответ."})
				break
			}
			loopSigs = append(loopSigs, sig)
			if len(loopSigs) > 60 {
				loopSigs = loopSigs[len(loopSigs)-60:]
			}

			var result string
			idx, ok := a.ToolIndex[name]
			if !ok {
				result = "ошибка: неизвестный тул " + name
			} else {
				var args map[string]any
				if err := json.Unmarshal([]byte(tc.Function.Arguments), &args); err != nil {
					args = map[string]any{}
				}
				ts := time.Now()
				r, err := a.Tools[idx].Handler(ctx, args)
				if err != nil {
					result = "ошибка: " + err.Error()
				} else {
					result = r
					if name == "web_search" || name == "web_fetch" { // запоминаем источники
						for _, u := range reURL.FindAllString(result, -1) {
							sources[strings.TrimRight(u, ".,;:")] = true
						}
					}
				}
				a.emit("tool_result", name, clampStr(result, 600), time.Since(ts))
			}
			a.Messages = append(a.Messages, Message{
				Role:       "tool",
				ToolCallID: tc.ID,
				Name:       name,
				Content:    result,
			})
		}
	}
	return "", errors.New("превышен лимит шагов агента")
}

// Reset — очищает историю диалога (сохраняя system prompt).
func (a *Agent) Reset() {
	a.Messages = a.Messages[:1]
}

// ============================================================================
// ГЛАВА 8. ТЕРМИНАЛ: RAW-РЕЖИМ И СТРОКОВЫЙ РЕДАКТОР (без внешних либ)
// ============================================================================

type termState struct {
	old syscall.Termios
	fd  int
}

// makeRaw переводит терминал в raw-режим, но СОХРАНЯЕТ OPOST (ONLCR):
// иначе '\n' не возвращает каретку и весь вывод «уезжает лесенкой».
func makeRaw(fd int) (*termState, error) {
	var old syscall.Termios
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd),
		uintptr(ioctlReadTermios), uintptr(unsafe.Pointer(&old)), 0, 0, 0); errno != 0 {
		return nil, errno
	}
	raw := old
	raw.Iflag &^= syscall.IXON | syscall.ICRNL | syscall.BRKINT | syscall.INPCK | syscall.ISTRIP
	raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	// OPOST намеренно НЕ трогаем: пусть терминал сам превращает \n в \r\n.
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd),
		uintptr(ioctlWriteTermios), uintptr(unsafe.Pointer(&raw)), 0, 0, 0); errno != 0 {
		return nil, errno
	}
	return &termState{old: old, fd: fd}, nil
}

func (t *termState) Restore() {
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(t.fd),
		uintptr(ioctlWriteTermios), uintptr(unsafe.Pointer(&t.old)), 0, 0, 0)
}

const (
	ioctlReadTermios  = 0x5401 // TCGETS
	ioctlWriteTermios = 0x5402 // TCSETS
)

func termSize() (w, h int) {
	type winsize struct{ Row, Col, X, Y uint16 }
	ws := &winsize{}
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(syscall.Stdout),
		uintptr(0x5413), uintptr(unsafe.Pointer(ws))); errno == 0 && ws.Col > 0 {
		return int(ws.Col), int(ws.Row)
	}
	return 80, 24
}

var reANSI = regexp.MustCompile("\x1b\\[[0-9;]*m")

// visibleWidth — ширина строки в ячейках терминала (без ANSI и всего до последнего \n).
func visibleWidth(s string) int {
	s = reANSI.ReplaceAllString(s, "")
	if k := strings.LastIndexByte(s, '\n'); k >= 0 {
		s = s[k+1:]
	}
	return utf8.RuneCountInString(s)
}

// lineEditor — редактор одной строки с историей и ГОРИЗОНТАЛЬНОЙ прокруткой:
// видимая часть никогда не шире терминала, поэтому перерисовка через \r+\033[K
// всегда попадает в одну строку и ничего не «уезжает» вниз.
type lineEditor struct {
	history []string
	hpos    int
	buf     []rune
	cur     int
	off     int // сдвиг окна прокрутки (в рунах)
	out     io.Writer
	prompt  string
	promptW int
}

func newLineEditor(out io.Writer, prompt string) *lineEditor {
	return &lineEditor{out: out, prompt: prompt, promptW: visibleWidth(prompt)}
}

// CompleteFunc возвращает кандидатов на дополнение по текущему буферу и позиции курсора.
type CompleteFunc func(buf []rune, cur int) []string

var completer CompleteFunc

var slashCommands = []string{
	"/help", "/tools", "/models", "/provider", "/providers", "/session", "/sessions",
	"/compact", "/plugins", "/plugins-reload", "/sandbox", "/workspace", "/reset",
	"/memory", "/stats", "/telegram", "/quit",
	"/chat", "/new", "/history", "/lang", "/steer", "/queue", "/settings",
	"/attach", "/detach", "/tasks", "/hub",
}

// applyCompletion вставляет общий префикс/кандидата в буфер.
func (le *lineEditor) applyCompletion() {
	if completer == nil {
		return
	}
	cands := completer(le.buf, le.cur)
	if len(cands) == 0 {
		fmt.Fprintf(le.out, "\a")
		return
	}
	// общий префикс всех кандидатов
	common := cands[0]
	for _, c := range cands[1:] {
		for !strings.HasPrefix(c, common) && common != "" {
			common = common[:len(common)-1]
		}
	}
	// заменяем текущее «слово» слева от курсора
	start := le.cur
	for start > 0 && le.buf[start-1] != ' ' {
		start--
	}
	word := string(le.buf[start:le.cur])
	if len(cands) == 1 || len(common) > len(word) {
		ins := common
		if len(cands) == 1 {
			ins = cands[0] + " "
		}
		tail := ins[len(word):]
		if len(tail) > 0 {
			for _, r := range tail {
				le.buf = append(le.buf, 0)
				copy(le.buf[le.cur+1:], le.buf[le.cur:])
				le.buf[le.cur] = r
				le.cur++
			}
			le.redraw()
		}
	}
	if len(cands) > 1 {
		fmt.Fprintf(le.out, "\r\n")
		w, _ := termSize()
		line := ""
		for _, c := range cands {
			if visibleWidth(line)+visibleWidth(c)+2 > w-4 {
				fmt.Fprintf(le.out, "%s\r\n", line)
				line = ""
			}
			line += col(cCyan, c) + "  "
		}
		if line != "" {
			fmt.Fprintf(le.out, "%s\r\n", line)
		}
		le.redraw()
	}
}

func (le *lineEditor) redraw() {
	w, _ := termSize()
	avail := w - le.promptW - 3 // запас под индикаторы « »
	if avail < 10 {
		avail = 10
	}
	// двигаем окно за курсором
	if le.off > le.cur {
		le.off = le.cur
	}
	if le.cur > le.off+avail {
		le.off = le.cur - avail
	}
	if le.off > 0 {
		avail-- // место под «
	}
	end := le.off + avail
	if end > len(le.buf) {
		end = len(le.buf)
	}
	left, right := "", ""
	if le.off > 0 {
		left = col(cDim, "«")
	}
	if end < len(le.buf) {
		right = col(cDim, "»")
	}
	fmt.Fprintf(le.out, "\r\033[K%s%s%s%s", le.prompt, left, string(le.buf[le.off:end]), right)
	if back := end - le.cur; back > 0 {
		fmt.Fprintf(le.out, "\033[%dD", back)
	}
}

func (le *lineEditor) ReadLine() (string, error) {
	le.buf = le.buf[:0]
	le.cur, le.off = 0, 0
	le.hpos = len(le.history)
	fmt.Fprintf(le.out, "\r\033[K%s", le.prompt)
	tmp := make([]byte, 64)
	for {
		n, err := os.Stdin.Read(tmp)
		if err != nil {
			return "", err
		}
		for i := 0; i < n; i++ {
			b := tmp[i]
			switch {
			case b == 13 || b == 10: // Enter
				fmt.Fprintf(le.out, "\r\n")
				line := string(le.buf)
				if strings.TrimSpace(line) != "" {
					le.history = append(le.history, line)
				}
				return line, nil
			case b == 3: // Ctrl+C
				return "", io.EOF
			case b == 4: // Ctrl+D
				if len(le.buf) == 0 {
					return "", io.EOF
				}
			case b == 12: // Ctrl+L — перерисовать
				le.redraw()
			case b == 9: // Tab — автодополнение
				le.applyCompletion()
			case b == 127 || b == 8: // Backspace
				if le.cur > 0 {
					le.buf = append(le.buf[:le.cur-1], le.buf[le.cur:]...)
					le.cur--
					le.redraw()
				}
			case b == 1: // Ctrl+A
				le.cur = 0
				le.redraw()
			case b == 5: // Ctrl+E
				le.cur = len(le.buf)
				le.redraw()
			case b == 21: // Ctrl+U
				le.buf = le.buf[:0]
				le.cur = 0
				le.redraw()
			case b == 23: // Ctrl+W — стереть слово
				for le.cur > 0 && le.buf[le.cur-1] == ' ' {
					le.buf = append(le.buf[:le.cur-1], le.buf[le.cur:]...)
					le.cur--
				}
				for le.cur > 0 && le.buf[le.cur-1] != ' ' {
					le.buf = append(le.buf[:le.cur-1], le.buf[le.cur:]...)
					le.cur--
				}
				le.redraw()
			case b == 27: // escape-последовательности
				if i+2 < n && tmp[i+1] == '[' {
					switch tmp[i+2] {
					case 'A': // up
						if le.hpos > 0 {
							le.hpos--
							le.buf = []rune(le.history[le.hpos])
							le.cur = len(le.buf)
							le.redraw()
						}
					case 'B': // down
						if le.hpos < len(le.history)-1 {
							le.hpos++
							le.buf = []rune(le.history[le.hpos])
						} else {
							le.hpos = len(le.history)
							le.buf = le.buf[:0]
						}
						le.cur = len(le.buf)
						le.redraw()
					case 'C': // right
						if le.cur < len(le.buf) {
							le.cur++
							le.redraw()
						}
					case 'D': // left
						if le.cur > 0 {
							le.cur--
							le.redraw()
						}
					case 'H': // home
						le.cur = 0
						le.redraw()
					case 'F': // end
						le.cur = len(le.buf)
						le.redraw()
					case '3': // delete (ESC [ 3 ~)
						if le.cur < len(le.buf) {
							le.buf = append(le.buf[:le.cur], le.buf[le.cur+1:]...)
							le.redraw()
						}
					}
					i += 2
					for i+1 < n && tmp[i] == '3' && tmp[i+1] == '~' { // съесть '~' у delete
						i++
					}
				}
			default:
				if b >= 32 || b >= 128 {
					seq := []byte{b}
					need := 0
					switch {
					case b&0xE0 == 0xC0:
						need = 1
					case b&0xF0 == 0xE0:
						need = 2
					case b&0xF8 == 0xF0:
						need = 3
					}
					for k := 0; k < need && i+1 < n; k++ {
						i++
						seq = append(seq, tmp[i])
					}
					r, _ := utf8.DecodeRune(seq)
					if r != utf8.RuneError && r != 0 {
						le.buf = append(le.buf, 0)
						copy(le.buf[le.cur+1:], le.buf[le.cur:])
						le.buf[le.cur] = r
						le.cur++
						le.redraw()
					}
				}
			}
		}
	}
}

// ============================================================================
// ГЛАВА 9. TUI: РЕНДЕР СОБЫТИЙ, СПИННЕР, MARKDOWN-ПОДСВЕТКА
// ============================================================================

var spinnerFrames = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}

type Spinner struct {
	msg    string
	stopCh chan struct{}
	doneCh chan struct{}
	active bool
	mu     sync.Mutex
}

func NewSpinner() *Spinner { return &Spinner{} }

func (s *Spinner) Start(msg string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.active {
		s.stopLocked()
	}
	s.msg = msg
	s.stopCh = make(chan struct{})
	s.doneCh = make(chan struct{})
	s.active = true
	fmt.Print("\033[?25l") // скрыть курсор
	go func() {
		defer close(s.doneCh)
		i := 0
		tick := time.NewTicker(80 * time.Millisecond)
		defer tick.Stop()
		for {
			select {
			case <-s.stopCh:
				fmt.Fprintf(os.Stdout, "\r\033[K\033[?25h") // очистить строку + вернуть курсор
				return
			case <-tick.C:
				fmt.Fprintf(os.Stdout, "\r%s %s%s%s", col(cCyan, spinnerFrames[i%len(spinnerFrames)]), cDim, msg, cReset)
				i++
			}
		}
	}()
}

func (s *Spinner) stopLocked() {
	if s.active {
		close(s.stopCh)
		<-s.doneCh
		s.active = false
	}
}

func (s *Spinner) Stop() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.stopLocked()
}

// renderMarkdownLite — минимальная подсветка markdown для терминала.
func renderMarkdownLite(text string) string {
	lines := strings.Split(text, "\n")
	var b strings.Builder
	inCode := false
	for _, ln := range lines {
		trim := strings.TrimSpace(ln)
		if strings.HasPrefix(trim, "```") {
			inCode = !inCode
			if inCode {
				b.WriteString(col(cGray, "┌─ код ─────────────────────────"))
			} else {
				b.WriteString(col(cGray, "└────────────────────────────────"))
			}
			b.WriteByte('\n')
			continue
		}
		if inCode {
			b.WriteString(col(cYellow, "  "+ln) + "\n")
			continue
		}
		switch {
		case strings.HasPrefix(trim, "#### "):
			b.WriteString(col(cBold+cBlue, strings.TrimPrefix(trim, "#### ")) + "\n")
		case strings.HasPrefix(trim, "### "):
			b.WriteString(col(cBold+cBlue, strings.TrimPrefix(trim, "### ")) + "\n")
		case strings.HasPrefix(trim, "## "):
			b.WriteString(col(cBold+cPurple, strings.TrimPrefix(trim, "## ")) + "\n")
		case strings.HasPrefix(trim, "# "):
			b.WriteString(col(cBold+cPurple, strings.ToUpper(strings.TrimPrefix(trim, "# "))) + "\n")
		case strings.HasPrefix(trim, "- ") || strings.HasPrefix(trim, "* "):
			b.WriteString(col(cCyan, "  • ") + renderInline(trim[2:]) + "\n")
		default:
			b.WriteString(renderInline(ln) + "\n")
		}
	}
	return b.String()
}

var (
	reBold   = regexp.MustCompile(`\*\*([^*]+)\*\*`)
	reCodeIn = regexp.MustCompile("`([^`]+)`")
	reLink   = regexp.MustCompile(`\[([^\]]+)\]\(([^)]+)\)`)
)

func renderInline(s string) string {
	s = reBold.ReplaceAllString(s, cBold+"$1"+cReset)
	s = reCodeIn.ReplaceAllString(s, cYellow+"$1"+cReset)
	s = reLink.ReplaceAllString(s, "$1 "+cCyan+cDim+"($2)"+cReset)
	return s
}

func printBanner(model string, tools []Tool) {
	// тема в духе opencode/tokyonight: фиолетово-синяя гамма, рамка, статус-строка
	const frame = "\x1b[38;2;130;170;255m"  // #82aaff
	const accent = "\x1b[38;2;192;153;255m" // #c099ff
	const muted = "\x1b[38;2;99;109;166m"   // #636da6
	w, _ := termSize()
	if w > 78 {
		w = 78
	}
	if w < 40 {
		w = 40
	}
	inner := w - 2
	row := func(s string) {
		pad := inner - visibleWidth(s) - 1
		if pad < 0 {
			pad = 0
		}
		fmt.Printf("%s│%s%s%*s%s│%s\n", frame, cReset, s, pad, "", frame, cReset)
	}
	fmt.Println()
	fmt.Printf("%s┌%s┐%s\n", frame, strings.Repeat("─", inner), cReset)
	row(" " + col(accent+cBold, "SYNERGY") + col(muted, "  автономный ИИ-агент"))
	row(" " + col(muted, "чистый Go • один файл • zero deps • статик-билд"))
	fmt.Printf("%s├%s┤%s\n", frame, strings.Repeat("─", inner), cReset)
	row(" " + col(cCyan, "модель:   ") + model)
	names := make([]string, len(tools))
	for i, t := range tools {
		names[i] = t.Spec.Function.Name
	}
	toolsLine := strings.Join(names, ", ")
	if visibleWidth(toolsLine) > inner-14 {
		toolsLine = trunc(toolsLine, inner-14)
	}
	row(" " + col(cCyan, "тулы ("+strconv.Itoa(len(tools))+"): ") + col(muted, toolsLine))
	fmt.Printf("%s└%s┘%s\n", frame, strings.Repeat("─", inner), cReset)
	fmt.Println()
	fmt.Println(col(cDim, "  Команды: /help /tools /model /provider /providers /session /sessions /compact /plugins /reset /memory /stats /quit"))
	fmt.Println(col(cDim, "  Клавиши: ↑/↓ история, Ctrl+A/E начало/конец, Ctrl+U очистить, Ctrl+D выход"))
	fmt.Println(col(cDim, strings.Repeat("─", w)))
}

