// ============================================================================
// ГЛАВА 10. СИСТЕМА ПЛАГИНОВ (JSON-RPC через stdin/stdout, по строке на сообщение)
// ============================================================================
//
// Плагин — любой исполняемый файл в ~/.config/gomni/plugins/ (или в каталоге
// из переменной GOMNI_PLUGINS). Язык любой: Python, Bash, Go, Node — лишь бы
// говорил по протоколу. Протокол — newline-delimited JSON:
//
//   -> {"method":"handshake","params":{"protocol":1}}
//   <- {"result":{"name":"meteo","version":"1.0","tools":[{"name":"weather",
//        "description":"Погода по городу","parameters":{"type":"object",
//        "properties":{"city":{"type":"string"}},"required":["city"]}}]}}
//
//   -> {"method":"tool_call","params":{"name":"weather","arguments":{"city":"Москва"}}}
//   <- {"result":"текст результата"}          или          {"error":"текст ошибки"}
//
//   -> {"method":"shutdown"}   (при выходе агента)
//
// Минимальный плагин на Python (~/.config/gomni/plugins/hello.py, chmod +x):
//
//   #!/usr/bin/env python3
//   import sys, json
//   for line in sys.stdin:
//       req = json.loads(line)
//       m, p = req.get("method"), req.get("params") or {}
//       if m == "handshake":
//           out = {"result": {"name": "hello", "version": "1.0", "tools": [{
//               "name": "hello_upper", "description": "Переводит текст в верхний регистр",
//               "parameters": {"type": "object",
//                   "properties": {"text": {"type": "string"}}, "required": ["text"]}}]}}
//       elif m == "tool_call":
//           out = {"result": str(p.get("arguments", {}).get("text", "")).upper()}
//       else:
//           out = {"result": None}
//       print(json.dumps(out), flush=True)

type rpcRequest struct {
	Method string `json:"method"`
	Params any    `json:"params,omitempty"`
}

type rpcResponse struct {
	Result json.RawMessage `json:"result"`
	Error  string          `json:"error,omitempty"`
}

// pluginProc — запущенный процесс плагина с каналами RPC.
type pluginProc struct {
	proc   *rawProc
	stdin  io.WriteCloser
	stdout *bufio.Scanner
	mu     sync.Mutex
}

// rpc — один синхронный вызов: пишем строку-запрос, ждём строку-ответ с таймаутом.
func (p *pluginProc) rpc(method string, params any, timeout time.Duration) (json.RawMessage, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	data, _ := json.Marshal(rpcRequest{Method: method, Params: params})
	if _, err := p.stdin.Write(append(data, '\n')); err != nil {
		return nil, err
	}
	type res struct {
		msg json.RawMessage
		err error
	}
	ch := make(chan res, 1)
	go func() {
		if p.stdout.Scan() {
			var resp rpcResponse
			if err := json.Unmarshal(p.stdout.Bytes(), &resp); err != nil {
				ch <- res{nil, fmt.Errorf("плагин вернул не-JSON: %s", trunc(p.stdout.Text(), 200))}
				return
			}
			if resp.Error != "" {
				ch <- res{nil, errors.New(resp.Error)}
				return
			}
			ch <- res{resp.Result, nil}
		} else {
			ch <- res{nil, errors.New("плагин закрыл stdout (упал?)")}
		}
	}()
	select {
	case r := <-ch:
		return r.msg, r.err
	case <-time.After(timeout):
		return nil, fmt.Errorf("плагин не ответил за %s", timeout)
	}
}

// Plugin — загруженный плагин: метаданные + его тулы.
type Plugin struct {
	Name    string
	Version string
	Tools   []Tool
	proc    *pluginProc
	path    string
}

// Close — шлёт shutdown и убивает процесс плагина.
func (p *Plugin) Close() {
	if p.proc == nil {
		return
	}
	p.proc.rpc("shutdown", nil, 2*time.Second)
	p.proc.proc.Kill()
	p.proc.proc.Close()
}

type handshakeResult struct {
	Name    string `json:"name"`
	Version string `json:"version"`
	Tools   []struct {
		Name        string         `json:"name"`
		Description string         `json:"description"`
		Parameters  map[string]any `json:"parameters"`
	} `json:"tools"`
}

// LoadPlugins — сканирует каталоги, запускает исполняемые файлы и делает handshake.
func LoadPlugins(dirs ...string) []*Plugin {
	var out []*Plugin
	seen := map[string]bool{}
	for _, dir := range dirs {
		if dir == "" {
			continue
		}
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, e := range entries {
			if e.IsDir() || seen[e.Name()] {
				continue
			}
			info, err := e.Info()
			if err != nil || !info.Mode().IsRegular() || info.Mode().Perm()&0o111 == 0 {
				continue // только исполняемые файлы
			}
			seen[e.Name()] = true
			path := filepath.Join(dir, e.Name())
			p, err := startPlugin(path)
			if err != nil {
				fmt.Println(col(cYellow, fmt.Sprintf("  ⚠ плагин %s: %v", e.Name(), err)))
				continue
			}
			fmt.Println(col(cDim, fmt.Sprintf("  ⚙ плагин %s v%s (%d тулов)", p.Name, p.Version, len(p.Tools))))
			out = append(out, p)
		}
	}
	return out
}

// startPlugin — запускает процесс и связывает его тулы с агентом.
func startPlugin(path string) (*Plugin, error) {
	// rawStart вместо os/exec: Go 1.24 зовёт pidfd_open при каждом запуске процесса,
	// а seccomp 32-битного Android убивает процесс за это (SIGSYS). Только fork+execve.
	rp, err := rawStart(path, nil, rawProcSpec{MergeStderr: false})
	if err != nil {
		return nil, err
	}
	proc := &pluginProc{proc: rp, stdin: rp.Stdin, stdout: bufio.NewScanner(rp.Stdout)}
	proc.stdout.Buffer(make([]byte, 0, 1<<20), 8<<20)
	if rp.Stderr != nil {
		go io.Copy(io.Discard, rp.Stderr) // stderr плагина в никуда — не мешает TUI
	}

	raw, err := proc.rpc("handshake", map[string]any{"protocol": 1}, 10*time.Second)
	if err != nil {
		rp.Kill()
		rp.Close()
		return nil, fmt.Errorf("handshake: %w", err)
	}
	var hs handshakeResult
	if err := json.Unmarshal(raw, &hs); err != nil {
		rp.Kill()
		rp.Close()
		return nil, fmt.Errorf("bad handshake json: %w", err)
	}
	if hs.Name == "" {
		hs.Name = filepath.Base(path)
	}
	if len(hs.Tools) == 0 {
		rp.Kill()
		rp.Close()
		return nil, errors.New("не экспортирует ни одного тула")
	}
	pl := &Plugin{Name: hs.Name, Version: hs.Version, proc: proc, path: path}
	if pl.Version == "" {
		pl.Version = "0"
	}
	for _, t := range hs.Tools {
		spec := makeSpec(t.Name, t.Description, map[string]any{}, nil)
		if t.Parameters != nil {
			spec.Function.Parameters = t.Parameters
		}
		toolName := t.Name
		pl.Tools = append(pl.Tools, Tool{
			Spec: spec,
			Handler: func(ctx context.Context, args map[string]any) (string, error) {
				raw, err := proc.rpc("tool_call", map[string]any{"name": toolName, "arguments": args}, 120*time.Second)
				if err != nil {
					return "", err
				}
				var s string
				if json.Unmarshal(raw, &s) == nil {
					return s, nil
				}
				return string(raw), nil
			},
		})
	}
	return pl, nil
}

// ============================================================================
// ГЛАВА 11. КОНФИГ (XDG), ИНТЕРАКТИВНАЯ НАСТРОЙКА, СЕССИИ
// ============================================================================

type Config struct {
	APIKey        string                  `json:"api_key,omitempty"`
	BaseURL       string                  `json:"base_url,omitempty"`
	Model         string                  `json:"model,omitempty"`
	Provider      string                  `json:"provider,omitempty"` // имя последнего выбранного провайдера (TUI)
	TelegramToken string                  `json:"telegram_token,omitempty"`
	Providers     map[string]*ProviderCfg `json:"providers,omitempty"`
	// Фейловер: если провайдер лёг (4 попытки + 5 мин паузы) — переключиться.
	FailoverEnabled bool   `json:"failover_enabled"` // по умолчанию true (zero-value false → трактуем как true, см. failoverOn)
	FailoverTarget  string `json:"failover_target,omitempty"`
	SidebarSide     string `json:"sidebar_side,omitempty"` // "left" (по умолчанию) | "right"
	Lang            string `json:"lang,omitempty"`         // "ru" (по умолчанию) | "en"
	TitleModel      string `json:"title_model,omitempty"`  // модель для заголовков чатов; пусто = текущая
}

func getConfigDir() string {
	dir := os.Getenv("XDG_CONFIG_HOME")
	if dir == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return "."
		}
		dir = filepath.Join(home, ".config")
	}
	old := filepath.Join(dir, "gomni")
	dir = filepath.Join(dir, "synergy")
	// одноразовая миграция: если новой папки нет, а старая есть — переносим
	if _, err := os.Stat(dir); os.IsNotExist(err) {
		if _, err2 := os.Stat(old); err2 == nil {
			if err3 := os.Rename(old, dir); err3 == nil {
				return dir
			}
		}
	}
	os.MkdirAll(dir, 0o755)
	return dir
}

// promptSecret — ввод с маскировкой '*' (через raw-режим, без внешних либ).
func promptSecret(label string) string {
	fmt.Print(label)
	ts, err := makeRaw(syscall.Stdin)
	if err != nil {
		r := bufio.NewReader(os.Stdin)
		s, _ := r.ReadString('\n')
		return strings.TrimSpace(s)
	}
	var buf []byte
	tmp := make([]byte, 1)
	for {
		if _, err := os.Stdin.Read(tmp); err != nil {
			break
		}
		b := tmp[0]
		switch {
		case b == '\r' || b == '\n':
			goto done
		case b == 3: // Ctrl+C
			ts.Restore()
			fmt.Print("\r\n")
			os.Exit(1)
		case b == 127 || b == 8:
			if len(buf) > 0 {
				buf = buf[:len(buf)-1]
				fmt.Print("\b \b")
			}
		default:
			buf = append(buf, b)
			fmt.Print("*")
		}
	}
done:
	ts.Restore()
	fmt.Print("\r\n")
	return strings.TrimSpace(string(buf))
}

func promptLine(r *bufio.Reader, label string) string {
	fmt.Print(label)
	s, _ := r.ReadString('\n')
	return strings.TrimSpace(s)
}

// loadOrSetupConfig — читает ~/.config/gomni/config.json; env переопределяет файл;
// при отсутствии ключа — интерактивная настройка с сохранением.
func loadOrSetupConfig() Config {
	cfgPath := filepath.Join(getConfigDir(), "config.json")
	var cfg Config
	if data, err := os.ReadFile(cfgPath); err == nil {
		json.Unmarshal(data, &cfg)
	}
	if v := os.Getenv("OPENAI_API_KEY"); v != "" {
		cfg.APIKey = v
	}
	if v := os.Getenv("OPENAI_BASE_URL"); v != "" {
		cfg.BaseURL = v
	}
	if v := os.Getenv("GOMNI_MODEL"); v != "" {
		cfg.Model = v
	}

	// Мастер настройки убран: TUI стартует сразу, ключи вводятся в окне настроек (Ctrl+S).
	if cfg.APIKey == "" && !isTerminal() {
		fmt.Fprintln(os.Stderr, col(cYellow, "⚠ OPENAI_API_KEY не задан — можно ввести позже в настройках TUI (Ctrl+S)."))
	}
	if cfg.Model == "" {
		cfg.Model = "gpt-4o-mini"
	}
	if cfg.BaseURL == "" {
		cfg.BaseURL = "https://api.openai.com/v1"
	}
	return cfg
}

// --- сессии: переживают перезапуск TUI ---

var curSession = "default"

var silentSessionLoad bool

func sessionsDir() string {
	d := filepath.Join(getConfigDir(), "sessions")
	os.MkdirAll(d, 0o755)
	return d
}

func sessionPath() string {
	name := reSessName.ReplaceAllString(curSession, "")
	if name == "" {
		name = "default"
	}
	return filepath.Join(sessionsDir(), name+".json")
}

var reSessName = regexp.MustCompile(`[^a-zA-Z0-9_\-]+`)

func saveSession(a *Agent) {
	msgs := a.Messages
	// не даём файлу сессии разрастаться бесконечно (20+ часов аптайма):
	// системный промпт + до 80 последних сообщений, грубый лимит по байтам
	if len(msgs) > 81 {
		kept := make([]Message, 0, 81)
		kept = append(kept, msgs[0])
		kept = append(kept, msgs[len(msgs)-80:]...)
		msgs = kept
	}
	total := 0
	for i := range msgs {
		total += len(msgs[i].Content)
	}
	for total > 400000 && len(msgs) > 3 { // ~400KB потолок
		msgs = append(msgs[:1], msgs[2:]...)
		total -= len(msgs[1].Content)
	}
	if b, err := json.Marshal(msgs); err == nil {
		tmp := sessionPath() + ".tmp"
		if os.WriteFile(tmp, b, 0o600) == nil {
			os.Rename(tmp, sessionPath()) // атомарная запись — не бьём сессию при обрыве
		}
	}
}

func loadSession(a *Agent) {
	b, err := os.ReadFile(sessionPath())
	if err != nil {
		return
	}
	var msgs []Message
	if json.Unmarshal(b, &msgs) == nil && len(msgs) > 1 {
		msgs[0] = a.Messages[0] // системный промпт всегда свежий
		a.Messages = msgs
		if !silentSessionLoad {
			fmt.Println(col(cDim, fmt.Sprintf("  (сессия %q: загружено %d сообщений — /reset чтобы очистить)", curSession, len(msgs)-1)))
		}
	}
}

func clearSession(a *Agent) {
	os.Remove(sessionPath())
	a.Reset()
}

func saveNamedSession(a *Agent, name string) {
	name = reSessName.ReplaceAllString(name, "")
	if name == "" {
		return
	}
	path := filepath.Join(sessionsDir(), name+".json")
	msgs := a.Messages
	if len(msgs) > 81 {
		kept := make([]Message, 0, 81)
		kept = append(kept, msgs[0])
		kept = append(kept, msgs[len(msgs)-80:]...)
		msgs = kept
	}
	if b, err := json.Marshal(msgs); err == nil {
		tmp := path + ".tmp"
		if os.WriteFile(tmp, b, 0o600) == nil {
			os.Rename(tmp, path)
		}
	}
}

func loadNamedSession(a *Agent, name string) {
	name = reSessName.ReplaceAllString(name, "")
	if name == "" {
		return
	}
	b, err := os.ReadFile(filepath.Join(sessionsDir(), name+".json"))
	if err != nil {
		return
	}
	var msgs []Message
	if json.Unmarshal(b, &msgs) == nil && len(msgs) > 1 {
		msgs[0] = a.Messages[0]
		a.Messages = msgs
	}
}

func listSessions() []string {
	entries, err := os.ReadDir(sessionsDir())
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		if strings.HasSuffix(e.Name(), ".json") {
			out = append(out, strings.TrimSuffix(e.Name(), ".json"))
		}
	}
	sort.Strings(out)
	return out
}

// deleteSessionFiles — удалить файл сессии по имени.
func deleteSessionFiles(name string) bool {
	name = reSessName.ReplaceAllString(name, "")
	if name == "" {
		return false
	}
	return os.Remove(filepath.Join(sessionsDir(), name+".json")) == nil
}

