// imageToDataURL читает файл картинки и кодирует в data: URL для vision-моделей.
func imageToDataURL(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	if len(data) > 10<<20 {
		return "", errors.New("картинка больше 10 МБ — слишком тяжёлая для vision-запроса")
	}
	mime := http.DetectContentType(data)
	if !strings.HasPrefix(mime, "image/") {
		return "", fmt.Errorf("%s: не картинка (%s)", filepath.Base(path), mime)
	}
	return "data:" + mime + ";base64," + base64.StdEncoding.EncodeToString(data), nil
}

// modelSupportsVision — грубая эвристика по имени модели.
func modelSupportsVision(model string) bool {
	m := strings.ToLower(model)
	for _, kw := range []string{"vision", "-vl", "vl-", "gpt-4o", "claude", "gemini", "qwen", "pixtral", "llava", "glm-4v", "kimi", "grok", "fable", "mimo"} {
		if strings.Contains(m, kw) {
			return true
		}
	}
	return false
}

// newUUID — простой UUIDv4 без зависимостей (для x-opencode-session).
func newUUID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return fmt.Sprintf("%d", time.Now().UnixNano())
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
		b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

// LookPathSafe resolves an executable without syscall faccessat2 (Android seccomp on 32-bit
// kills faccessat2 with SIGSYS). Uses os.Stat only — no exec bits probing via faccessat.
// currentLLM — текущий LLM-клиент для субагентов (delegate/delegate_parallel).
var currentLLM *LLMClient

// globalMCPServers — живые MCP-клиенты; attachMCP вешает их тулы на нового агента (чаты TUI).
var globalMCPServers []*mcpClient

func attachMCP(a *Agent) int {
	n := 0
	for _, c := range globalMCPServers {
		before := len(a.Tools)
		c.registerMCPTools(a)
		n += len(a.Tools) - before
	}
	n += attachMCPHTTP(a) // + удалённые HTTP-серверы
	return n
}

// androidShellRunner возвращает функцию выполнения shell-команд на устройстве:
// через Shizuku (rish), иначе через adb shell, иначе ошибка с инструкцией.
func androidShellRunner() (func(cmd string) (string, error), error) {
	if rish, err := LookPathSafe("rish"); err == nil {
		return func(cmd string) (string, error) {
			ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
			defer cancel()
			out, err := runRawCombined(ctx, "", nil, 60*time.Second, rish, "-c", cmd)
			return trunc(out, 6000), err
		}, nil
	}
	if adb, err := LookPathSafe("adb"); err == nil {
		return func(cmd string) (string, error) {
			ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
			defer cancel()
			out, err := runRawCombined(ctx, "", nil, 60*time.Second, adb, "shell", cmd)
			return trunc(out, 6000), err
		}, nil
	}
	return nil, errors.New("ни Shizuku (rish), ни adb не найдены. Установи: pkg install shizuku — или скачай rish и запусти Shizuku на устройстве")
}

func LookPathSafe(name string) (string, error) {
	if name == "" {
		return "", fmt.Errorf("empty name")
	}
	if strings.ContainsRune(name, '/') {
		if st, err := os.Stat(name); err == nil && !st.IsDir() && st.Mode()&0111 != 0 {
			return name, nil
		}
		return "", fmt.Errorf("not executable: %s", name)
	}
	pathEnv := os.Getenv("PATH")
	for _, dir := range strings.Split(pathEnv, ":") {
		if dir == "" {
			dir = "."
		}
		full := dir + "/" + name
		if st, err := os.Stat(full); err == nil && !st.IsDir() && st.Mode()&0111 != 0 {
			return full, nil
		}
	}
	// Termux fallback paths
	for _, dir := range []string{"/data/data/com.termux/files/usr/bin", "/system/bin"} {
		full := dir + "/" + name
		if st, err := os.Stat(full); err == nil && !st.IsDir() && st.Mode()&0111 != 0 {
			return full, nil
		}
	}
	return "", fmt.Errorf("%s not found in PATH", name)
}

func main() {
	var oneshot, noStream, telegramMode, netTestMode, serveMode, loginMode bool
	var promptArg, sessionArg string
	port := 8787
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-oneshot":
			oneshot = true
			if i+1 < len(args) {
				promptArg = args[i+1]
				i++
			}
		case "-no-stream":
			noStream = true
		case "-insecure", "--insecure":
			insecureTLS = true
		case "-test-net":
			netTestMode = true
		case "-telegram", "-tg":
			telegramMode = true
		case "-serve", "--serve":
			serveMode = true
		case "-login", "--login", "login":
			loginMode = true
		case "-port", "--port":
			if i+1 < len(args) {
				fmt.Sscanf(args[i+1], "%d", &port)
				i++
			}
		case "-session", "-s":
			if i+1 < len(args) {
				sessionArg = args[i+1]
				i++
			}
		case "-h", "--help":
			fmt.Println("synergy-harness [-oneshot \"запрос\"] [-no-stream] [-serve [-port N]]")
			return
		default:
			if promptArg == "" {
				promptArg = args[i]
			}
		}
	}

	if sessionArg != "" {
		curSession = sessionArg
	}
	cfg := loadOrSetupConfig()
	if cfg.APIKey == "" {
		fmt.Println(col(cYellow, "  ⚠ API-ключ не настроен — LLM-запросы могут отклоняться. /providers для настройки."))
	}

	workdir, _ := os.Getwd()
	workdir = getenv("GOMNI_WORKDIR", workdir)
	ensureWorkspace(workdir) // автосоздание workspace: SOUL.md, AGENT.md, memory/, plugins/...
	llm := NewLLMClient()
	currentLLM = llm // субагенты (delegate/delegate_parallel) наследуют его
	if netTestMode {
		runNetTest()
	}
	llm.APIKey = cfg.APIKey
	if cfg.BaseURL != "" {
		llm.BaseURL = strings.TrimRight(cfg.BaseURL, "/")
	}
	if cfg.Model != "" {
		llm.Model = cfg.Model
	}

	// Загрузка плагинов: ~/.config/gomni/plugins + $GOMNI_PLUGINS
	plugins := LoadPlugins(filepath.Join(getConfigDir(), "plugins"), getenv("GOMNI_PLUGINS", ""))
	defer func() {
		for _, p := range plugins {
			p.Close()
		}
	}()

	// MCP-серверы из ~/.config/gomni/mcp.json (тулы регистрируются у каждого агента)
	writeMCPExample()
	mcpStdio, mcpHTTP := LoadMCPAll() // stdio (command:) + удалённые (url:) серверы
	defer func() {
		for _, c := range mcpStdio {
			c.close()
		}
	}()
	globalMCPServers = mcpStdio
	globalMCPHTTP = mcpHTTP

	agent := NewAgent(llm, workdir, plugins...)
	for _, c := range mcpStdio {
		c.registerMCPTools(agent)
	}
	attachMCPHTTP(agent)
	agent.StreamUI = !noStream && isTerminal()

	// --- HTTP-сервер (хаб + API, headless-режим) ---
	if loginMode {
		if err := CodexDeviceLogin(context.Background(), os.Stdout); err != nil {
			fmt.Fprintln(os.Stderr, "login:", err)
			os.Exit(1)
		}
		os.Exit(0)
	}
	if serveMode {
		os.Exit(runServer(cfg, llm, workdir, plugins, port))
	}

	// --- Telegram-бот (демон, крутится 20+ часов с backoff и recover) ---
	if telegramMode {
		token := getenv("TELEGRAM_BOT_TOKEN", cfg.TelegramToken)
		if token == "" {
			fmt.Fprintln(os.Stderr, col(cRed, "✗ Нужен токен бота: export TELEGRAM_BOT_TOKEN=... или telegram_token в config.json"))
			os.Exit(1)
		}
		bot := &TGBot{
			Token: token, LLM: llm, Workdir: workdir, Plugins: plugins,
			Agents: map[int64]*Agent{},
			Logf:   func(f string, a ...any) { fmt.Println(col(cDim, "  [tg] "+fmt.Sprintf(f, a...))) },
		}
		fmt.Println(col(cGreen, "  ✓ Telegram-бот запущен (Ctrl+C для остановки)"))
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		bot.RunForever(ctx)
		return
	}

	// --- oneshot-режим ---
	if oneshot && promptArg != "" {
		sp := NewSpinner()
		streaming := false
		agent.OnEvent = func(ev AgentEvent) {
			switch ev.Kind {
			case "tool_call":
				if streaming {
					fmt.Println()
					streaming = false
				}
				sp.Start("тулы: " + ev.Title)
			case "tool_result":
				sp.Stop()
				fmt.Printf("%s %s\n", col(cGreen, "✓ "+ev.Title), col(cDim, "("+ev.Elapsed.Round(time.Millisecond).String()+")"))
				fmt.Println(col(cGray, indent(trunc(ev.Body, 300), "    ")))
			case "delta":
				sp.Stop()
				fmt.Print(ev.Body)
				streaming = true
			case "think":
				sp.Stop()
				fmt.Println(col(cDim, italic(ev.Body)))
			case "answer":
				sp.Stop()
				fmt.Println(renderMarkdownLite(ev.Body))
			case "answer_done":
				fmt.Println()
			}
		}
		if !agent.StreamUI {
			sp.Start("думаю...")
		}
		_, err := agent.Run(context.Background(), promptArg)
		sp.Stop()
		if err != nil {
			fmt.Fprintln(os.Stderr, col(cRed, "ошибка: "+err.Error()))
			os.Exit(1)
		}
		return
	}

	// --- TUI-режим (Bubble Tea: центр-ввод, панель сессий, мышь, уведомления) ---
	if !isTerminal() {
		fmt.Fprintln(os.Stderr, col(cYellow, "stdout — не терминал; используйте -oneshot \"запрос\""))
		os.Exit(1)
	}
	silentSessionLoad = true
	code := runBubbleTUI(cfg, llm, workdir, plugins)
	os.Exit(code)
}

func italic(s string) string { return "\033[3m" + s + "\033[23m" }

func indent(s, prefix string) string {
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		lines[i] = prefix + l
	}
	return strings.Join(lines, "\n")
}

func padRight(s string, n int) string {
	for len([]rune(s)) < n {
		s += " "
	}
	return s
}

// silence unused imports guard
var (
	_ = runtime.GOOS
	_ = startTime
)

// ============================================================================
// ГЛАВА 13. PRODUCTION-ЯДРО: DNS-FALLBACK, ПРОВАЙДЕРЫ, СЕССИИ, СЖАТИЕ КОНТЕКСТА,
// СУБАГЕНТЫ, АНТИ-ЦИКЛ/АНТИ-ГАЛЛЮЦИНАЦИИ, USERSPACE-САНДБОКС, TELEGRAM
// ============================================================================

// ---------- 13.1 DNS с fallback (фикс "lookup ... on [::1]:53: connection refused") ----------
// В Termux и на части девайсов /etc/resolv.conf указывает на мёртвый локальный
// резолвер. Мы перебираем nameserver'ы из resolv.conf + публичные fallback'и
// (8.8.8.8, 1.1.1.1, 9.9.9.9), пока один не ответит. Свой список: GOMNI_DNS="1.1.1.1:53,8.8.8.8:53".

func parseResolvConf() []string {
	var out []string
	if data, err := os.ReadFile("/etc/resolv.conf"); err == nil {
		for _, ln := range strings.Split(string(data), "\n") {
			f := strings.Fields(ln)
			if len(f) == 2 && f[0] == "nameserver" {
				h := f[1]
				if strings.Contains(h, ":") && !strings.HasPrefix(h, "[") {
					h = "[" + h + "]"
				}
				out = append(out, h+":53")
			}
		}
	}
	if v := os.Getenv("GOMNI_DNS"); v != "" {
		out = out[:0]
		for _, s := range strings.Split(v, ",") {
			if s = strings.TrimSpace(s); s != "" {
				out = append(out, s)
			}
		}
	}
	out = append(out, "8.8.8.8:53", "1.1.1.1:53", "9.9.9.9:53")
	return out
}

func newFallbackResolver() *net.Resolver {
	servers := parseResolvConf()
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
			var lastErr error
			for _, srv := range servers {
				d := net.Dialer{Timeout: 2500 * time.Millisecond}
				conn, err := d.DialContext(ctx, "udp", srv)
				if err == nil {
					return conn, nil
				}
				lastErr = err
			}
			return nil, fmt.Errorf("DNS недоступен (пробовал %s): %w", strings.Join(servers, ", "), lastErr)
		},
	}
}

var (
	sharedResolver      = newFallbackResolver()
	sharedDialer        = &net.Dialer{Timeout: 15 * time.Second, KeepAlive: 30 * time.Second, Resolver: sharedResolver}
	sharedHTTPTransport = &http.Transport{
		MaxIdleConns:        16,
		IdleConnTimeout:     90 * time.Second,
		TLSHandshakeTimeout: 15 * time.Second,
		DialContext:         sharedDialer.DialContext,
		TLSClientConfig:     newTLSClientConfig(),
	}
	sharedHTTPClient = &http.Client{Timeout: 60 * time.Second, Transport: sharedHTTPTransport}
)

// isTransientErr — сетевая/временная ошибка, которую имеет смысл повторить.
func isTransientErr(err error) bool {
	s := strings.ToLower(err.Error())
	for _, pat := range []string{"timeout", "eof", "reset", "refused", "429", "502", "503", "504", "tls", "no route", "temporary"} {
		if strings.Contains(s, pat) {
			return true
		}
	}
	return false
}

func envInt(key string, def int) int {
	if v, err := strconv.Atoi(os.Getenv(key)); err == nil && v > 0 {
		return v
	}
	return def
}

// ---------- 13.2 Провайдеры и модели ----------

type ProviderCfg struct {
	BaseURL string `json:"base_url"`
	APIKey  string `json:"api_key,omitempty"`
	Model   string `json:"model,omitempty"`
}

type providerPreset struct {
	Name, BaseURL, DefaultModel, KeyEnv string
}

var providerPresets = []providerPreset{
	{"zen-free", "https://opencode.ai/zen/v1", "big-pickle", ""},
	{"zen", "https://opencode.ai/zen/v1", "mimo-v2.5-free", "OPENAI_API_KEY"},
	{"openrouter", "https://openrouter.ai/api/v1", "openai/gpt-4o-mini", "OPENROUTER_API_KEY"},
}

func findPreset(name string) *providerPreset {
	for i := range providerPresets {
		if providerPresets[i].Name == name {
			return &providerPresets[i]
		}
	}
	return nil
}

// applyProvider переключает LLM-клиента на провайдера (из конфига или пресета).
func applyProvider(llm *LLMClient, cfg *Config, name string) error {
	pc, ok := cfg.Providers[name]
	if !ok {
		if p := findPreset(name); p != nil {
			pc = &ProviderCfg{BaseURL: p.BaseURL, Model: p.DefaultModel}
			if k := os.Getenv(p.KeyEnv); k != "" {
				pc.APIKey = k
			} else if cfg.APIKey != "" && (p.KeyEnv == "OPENAI_API_KEY" || p.KeyEnv == "") {
				pc.APIKey = cfg.APIKey
			}
		} else {
			return fmt.Errorf("неизвестный провайдер %q — /providers для списка, /provider add <имя> <base_url> [ключ] [модель] чтобы добавить", name)
		}
	}
	llm.BaseURL = strings.TrimRight(pc.BaseURL, "/")
	if pc.APIKey != "" {
		llm.APIKey = pc.APIKey
	}
	if pc.Model != "" {
		llm.Model = pc.Model
	}
	return nil
}

func saveConfig(cfg Config) {
	if b, err := json.MarshalIndent(cfg, "", "  "); err == nil {
		os.WriteFile(filepath.Join(getConfigDir(), "config.json"), b, 0o600)
	}
}

// ---------- 13.3 Сжатие контекста (через сабагента) ----------

func (a *Agent) contextSize() int {
	n := 0
	for _, m := range a.Messages {
		n += len(m.Content)
		for _, tc := range m.ToolCalls {
			n += len(tc.Function.Arguments)
		}
	}
	return n
}

// compactContext сжимает старую часть диалога в сводку отдельным LLM-вызовом.
// Это и есть "сжатие через другого агента": изолированный запрос со своим промптом.
func (a *Agent) compactContext(ctx context.Context) (string, error) {
	if len(a.Messages) < 10 {
		return "", errors.New("контекст мал — сжимать нечего")
	}
	cut := len(a.Messages) - 6 // системный + сводка + 6 последних остаются как есть
	if cut <= 1 {
		return "", errors.New("нечего сжимать")
	}
	var b strings.Builder
	for _, m := range a.Messages[1:cut] {
		fmt.Fprintf(&b, "[%s] %s\n", m.Role, clampStr(m.Content, 1500))
		for _, tc := range m.ToolCalls {
			fmt.Fprintf(&b, "  (вызов тула %s: %s)\n", tc.Function.Name, trunc(tc.Function.Arguments, 200))
		}
	}
	req := ChatRequest{Messages: []Message{
		{Role: "system", Content: "Ты — модуль сжатия памяти агента. Сожми протокол диалога в плотную сводку на языке диалога: цели пользователя, принятые решения, важные факты/числа/URL, состояние задач, договорённости. Без воды, маркированный список, до 1500 знаков."},
		{Role: "user", Content: clampStr(b.String(), 60000)},
	}}
	var summary string
	if resp, err := a.LLM.Complete(ctx, req); err != nil {
		summary = "[LLM-сводка не удалась: " + err.Error() + "] Старый контекст отброшен, опирайся на последние сообщения."
	} else {
		summary = resp.Choices[0].Message.Content
	}
	before := a.contextSize()
	kept := make([]Message, 0, len(a.Messages)-cut+2)
	kept = append(kept, a.Messages[0])
	kept = append(kept, Message{Role: "assistant", Content: "📦 СЖАТАЯ ПАМЯТЬ (всё важное из начала диалога):\n" + summary})
	kept = append(kept, a.Messages[cut:]...)
	a.Messages = kept
	return fmt.Sprintf("контекст сжат: %d → %d байт", before, a.contextSize()), nil
}

// maybeCompact — автозапуск сжатия при разрастании (лимит: GOMNI_COMPACT_CHARS, по умолчанию 90000).
// modelContextChars — грубая оценка окна контекста в символах (~4 chars/token).
func (a *Agent) modelContextChars() int {
	name := strings.ToLower(a.LLM.Model)
	switch {
	case strings.Contains(name, "32k"):
		return 32000 * 4
	case strings.Contains(name, "mini"), strings.Contains(name, "flash"), strings.Contains(name, "haiku"):
		return 128000 * 4
	case strings.Contains(name, "70b"), strings.Contains(name, "llama"):
		return 128000 * 4
	}
	return 128000 * 4 // консервативный дефолт
}

func (a *Agent) maybeCompact(ctx context.Context) {
	limit := envInt("GOMNI_COMPACT_CHARS", a.modelContextChars()*9/10) // 90% окна
	if a.contextSize() > limit {
		a.emit("info", "compact", "контекст разросся — сжимаю через сабагента-суммаризатора…", 0)
		if msg, err := a.compactContext(ctx); err == nil {
			a.emit("info", "compact", msg, 0)
		}
	}
}

// ---------- 13.3.5 Self-repair: агент пишет плагины сам себе ----------
// write_plugin создаёт плагин в ~/.config/gomni/plugins, проверяет handshake
// и при успехе сразу регистрирует его тулы в текущем агенте. Так агент может
// чинить себя: "не хватает тула X" → пишет плагин → тул появляется.

func (a *Agent) registerSelfRepair(workdir string) {
	a.RegisterTool(makeSpec("write_plugin",
		`Создать и сразу подключить плагин Synergy Harness. Плагин — исполняемый скрипт (любой язык), общающийся newline-delimited JSON по stdin/stdout. Протокол: на {"method":"handshake"} ответь {"result":{"name":"имя","version":"1.0","tools":[{"name":"имя_тула","description":"...","parameters":{"type":"object","properties":{...},"required":[...]}}]}}; на {"method":"tool_call","params":{"name":"...","arguments":{...}}} ответь {"result":"текст"} или {"error":"текст"}; на {"method":"shutdown"} — выход. Каждый ответ — ОДНА строка JSON с flush (в Python: print(json.dumps(out), flush=True)). После записи плагин автоматически проверяется handshake и регистрируется — дальше его тулы вызываются как встроенные.`,
		map[string]any{
			"filename": pStr("имя файла, напр. weather.py (будет в ~/.config/gomni/plugins/)"),
			"content":  pStr("полный исходник плагина (со shebang, напр. #!/usr/bin/env python3)"),
		}, []string{"filename", "content"}),
		func(ctx context.Context, args map[string]any) (string, error) {
			fname := filepath.Base(strArg(args, "filename"))
			content := strArg(args, "content")
			if fname == "" || content == "" {
				return "", errors.New("нужны filename и content")
			}
			if strings.Contains(fname, "..") {
				return "", errors.New("недопустимое имя файла")
			}
			dir := filepath.Join(getConfigDir(), "plugins")
			os.MkdirAll(dir, 0o755)
			path := filepath.Join(dir, fname)
			if err := os.WriteFile(path, []byte(content), 0o755); err != nil {
				return "", err
			}
			// проверяем handshake и регистрируем
			p, err := startPlugin(path)
			if err != nil {
				os.Remove(path)
				return "", fmt.Errorf("плагин записан, но handshake не прошёл (удалён): %w", err)
			}
			var names []string
			for _, t := range p.Tools {
				a.RegisterTool(t.Spec, t.Handler)
				names = append(names, t.Spec.Function.Name)
			}
			return fmt.Sprintf("OK: плагин %s v%s подключён, тулы: %s", p.Name, p.Version, strings.Join(names, ", ")), nil
		})
}

// ---------- 13.4 Субагент (delegate) ----------

func (a *Agent) registerRuntimeTools(workdir string) {
	a.RegisterTool(makeSpec("delegate",
		"Поручить независимую подзадачу субагенту (отдельный контекст, те же тулы, лимит 8 шагов). Используй для параллельных исследований, проверки фактов, черновиков. Возвращает итоговый ответ субагента.",
		map[string]any{"task": pStr("полная постановка подзадачи для субагента")}, []string{"task"}),
		func(ctx context.Context, args map[string]any) (out string, err error) {
			task := strArg(args, "task")
			if task == "" {
				return "", errors.New("пустая task")
			}
			defer func() { // субагент не должен ронять основной процесс
				if r := recover(); r != nil {
					out, err = "", fmt.Errorf("субагент упал: %v", r)
				}
			}()
			sub := &Agent{LLM: a.LLM, MaxSteps: 8}
			sub.Tools = BuildTools(workdir)
			sub.ToolIndex = map[string]int{}
			for i, t := range sub.Tools {
				sub.ToolIndex[t.Spec.Function.Name] = i
			}
			sub.Messages = []Message{{Role: "system", Content: "Ты — субагент Synergy Harness. Выполни порученную подзадачу автономно и верни только итоговый результат: кратко, точно, со ссылками на источники. Не задавай встречных вопросов."}}
			ctx2, cancel := context.WithTimeout(ctx, 3*time.Minute)
			defer cancel()
			res, rerr := sub.Run(ctx2, "Подзадача: "+task)
			if rerr != nil {
				return "", rerr
			}
			return clampStr(res, 8000), nil
		})
}

// ---------- 13.5 Анти-галлюцинации ----------

var reURL = regexp.MustCompile(`https?://[^\s)\]"'<>` + "`" + `]+`)

// checkHallucinations сверяет URL'ы финального ответа с тем, что реально
// возвращали тулы в этом запуске. Неподтверждённые ссылки помечаются.
func checkHallucinations(answer string, sources map[string]bool) string {
	if len(sources) == 0 {
		return answer
	}
	var bad []string
	for _, u := range reURL.FindAllString(answer, -1) {
		u = strings.TrimRight(u, ".,;:")
		if !sources[u] {
			bad = append(bad, u)
		}
	}
	if len(bad) > 0 {
		answer += "\n\n⚠️ [анти-галлюцинации] ссылки не из выдачи тулов (проверь вручную): " + strings.Join(bad, ", ")
	}
	return answer
}

// ---------- Workspace: автосоздание и загрузка (идея picoclaw) ----------
// GOMNI_WORKSPACE или workdir/.gomni — дом агента: SOUL.md (характер),
// AGENT.md (правила проекта), memory/, skills/, plugins/, sandbox/.

func workspaceDir(workdir string) string {
	if v := os.Getenv("GOMNI_WORKSPACE"); v != "" {
		return v
	}
	return filepath.Join(workdir, ".gomni")
}

var defaultSoul = `# Soul — характер Synergy Harness

- Прямой и по делу, без корпоративной воды
- Честный: не знаю — говорю и предлагаю, как проверить
- Лёгкий сухой юмор уместен, но не в ущерб точности
- Сначала сделай, потом отчитайся
`

var defaultPluginsMD = `# PLUGINS.md — как писать плагины для Synergy Harness (мануал для агента)

Ты можешь сам расширять себя плагинами. Прочитай этот файл целиком через read_file, когда пользователь просит новую возможность, которой нет во встроенных тулах.

## Формат
Плагин — исполняемый файл в ~/.config/gomni/plugins/ (или $GOMNI_PLUGINS), общающийся с агентом
по stdin/stdout построчным JSON-RPC:

1. При старте агент отправляет: {"method":"handshake"}
   Ответь: {"name":"myplugin","version":"1.0","tools":[{"name":"my_tool","description":"...","parameters":{"type":"object","properties":{...},"required":[...]}}]}
2. На вызов тула приходит: {"method":"tool_call","id":N,"tool":"my_tool","args":{...}}
   Ответь ровно одной строкой: {"id":N,"result":"текст результата"} или {"id":N,"error":"описание"}
3. {"method":"shutdown"} — завершись.

## Пример (Python)
#!/usr/bin/env python3
import sys, json
def reply(obj): sys.stdout.write(json.dumps(obj)+"\n"); sys.stdout.flush()
for line in sys.stdin:
    req = json.loads(line)
    if req.get("method") == "handshake":
        reply({"name":"hello","version":"1.0","tools":[{"name":"shout","description":"UPPERCASE text","parameters":{"type":"object","properties":{"text":{"type":"string"}},"required":["text"]}}]})
    elif req.get("method") == "tool_call":
        if req["tool"] == "shout":
            reply({"id":req["id"],"result":req["args"]["text"].upper()})
        else:
            reply({"id":req["id"],"error":"unknown tool"})
    elif req.get("method") == "shutdown":
        break

## Как добавить себе плагин (self-repair)
1. Вызови тул write_plugin с полем name (имя файла) и code (полный исходник, начинай с shebang).
2. Плагин сразу регистрируется — его тулы доступны в этом же диалоге.
3. Если плагин упал — прочитай ошибку из tool_result, исправь код и перезапиши через write_plugin.

## Правила
- Одна строка = один JSON, без лишнего вывода в stdout (логируй в stderr).
- Отвечай на tool_call не дольше 60 секунд.
- Делай тулы маленькими и однозадачными; описания — на русском, конкретными.
`

var defaultAgentMD = `# AGENT.md — правила этого workspace

- Язык ответов: как у пользователя
- Код: zero-dependency, статическая сборка (CGO_ENABLED=0), целевые платформы: linux/amd64, android/arm64
- Перед правками читай файлы, не угадывай содержимое
- Найденные в сети факты — только со ссылками из выдачи тулов
`

func ensureWorkspace(workdir string) string {
	ws := workspaceDir(workdir)
	for _, sub := range []string{"", "memory", "skills", "plugins", "sandbox", "sessions"} {
		os.MkdirAll(filepath.Join(ws, sub), 0o755)
	}
	writeIfAbsent := func(name, content string) {
		p := filepath.Join(ws, name)
		if _, err := os.Stat(p); os.IsNotExist(err) {
			os.WriteFile(p, []byte(content), 0o644)
		}
	}
	writeIfAbsent("SOUL.md", defaultSoul)
	writeIfAbsent("AGENT.md", defaultAgentMD)
	writeIfAbsent("PLUGINS.md", defaultPluginsMD)
	return ws
}

// workspaceContext — собирает SOUL.md + AGENT.md в добавку к системному промпту.
func workspaceContext(workdir string) string {
	ws := workspaceDir(workdir)
	var b strings.Builder
	for _, f := range []string{"SOUL.md", "AGENT.md"} {
		if data, err := os.ReadFile(filepath.Join(ws, f)); err == nil && len(data) > 0 {
			fmt.Fprintf(&b, "\n\n%s:\n%s", f, clampStr(string(data), 3000))
		}
	}
	return b.String()
}

func sandboxEnabled() bool {
	v := os.Getenv("SYNERGY_SANDBOX")
	if v == "" {
		v = os.Getenv("GOMNI_SANDBOX")
	}
	return v != "off"
}

// ---------- 13.6 Userspace-сандбокс (без рута, работает и в Termux) ----------
// Режим 1 (по умолчанию): изоляция окружения — команда работает в sandbox-root,
// PATH урезан до whitelist'а бинарей, env очищен (никаких API-ключей).
// Режим 2 (GOMNI_SANDBOX_PROOT=1): если установлен proot — настоящая
// изоляция ФС через proot -r (root не нужен). Интерфейс SandboxBackend —
// заготовка под будущий remote/docker-бэкенд.

type SandboxBackend interface {
	Root() string
	Run(ctx context.Context, command string) (string, error)
	Push(srcRel string) (string, error)         // copy-to-sandbox
	Pull(srcRel, dstRel string) (string, error) // copy-from-sandbox
}

type LocalSandbox struct {
	root     string
	workdir  string
	prepared bool
}

func NewLocalSandbox(workdir string) *LocalSandbox {
	root := getenv("GOMNI_SANDBOX_ROOT", filepath.Join(getConfigDir(), "sandbox"))
	os.MkdirAll(filepath.Join(root, "bin"), 0o755)
	os.MkdirAll(filepath.Join(root, "tmp"), 0o755)
	return &LocalSandbox{root: root, workdir: workdir}
}

func (s *LocalSandbox) Root() string { return s.root }

var sandboxAllow = []string{
	"sh", "ls", "cat", "echo", "printf", "grep", "sed", "awk", "head", "tail",
	"wc", "sort", "uniq", "date", "pwd", "mkdir", "rm", "rmdir", "touch", "cp",
	"mv", "tr", "cut", "find", "xargs", "uname", "sleep", "true", "false", "env",
	"python3", "python", "node", "curl", "wget", "tar", "gzip", "base64",
}

// prepareBin наполняет sandbox/bin симлинками на whitelisted-бинари.
func (s *LocalSandbox) prepareBin() {
	if s.prepared {
		return
	}
	allow := append([]string{}, sandboxAllow...)
	if extra := os.Getenv("GOMNI_SANDBOX_EXTRA"); extra != "" {
		allow = append(allow, strings.Split(extra, ",")...)
	}
	for _, name := range allow {
		if p, err := LookPathSafe(strings.TrimSpace(name)); err == nil {
			dst := filepath.Join(s.root, "bin", name)
			os.Remove(dst)
			os.Symlink(p, dst)
		}
	}
	s.prepared = true
}

func (s *LocalSandbox) scrubEnv() []string {
	return []string{
		"PATH=" + filepath.Join(s.root, "bin"),
		"HOME=" + s.root,
		"TMPDIR=" + filepath.Join(s.root, "tmp"),
		"LANG=C.UTF-8", "TERM=dumb", "USER=sandbox", "GOMNI_SANDBOX=1",
	}
}

func (s *LocalSandbox) Run(ctx context.Context, command string) (string, error) {
	s.prepareBin()
	cctx, cancel := context.WithTimeout(ctx, 60*time.Second)
	defer cancel()
	var bin string
	var sargs []string
	if proot, err := LookPathSafe("proot"); err == nil && os.Getenv("GOMNI_SANDBOX_PROOT") == "1" {
		// Настоящая изоляция ФС: корень = sandbox, системные каталоги бинарей подмонтированы read-only.
		args := []string{"-r", s.root, "-w", "/"}
		seen := map[string]bool{}
		bind := func(dir string) {
			if dir != "" && !seen[dir] {
				if st, err := os.Stat(dir); err == nil && st.IsDir() {
					args = append(args, "-b", dir)
					seen[dir] = true
				}
			}
		}
		if entries, _ := os.ReadDir(filepath.Join(s.root, "bin")); true {
			for _, e := range entries {
				if target, err := filepath.EvalSymlinks(filepath.Join(s.root, "bin", e.Name())); err == nil {
					bind(filepath.Dir(target))
				}
			}
		}
		bind("/etc")
		bind("/dev")
		bind("/proc")
		args = append(args, "/bin/sh", "-c", command)
		bin, sargs = proot, args
	} else {
		bin, sargs = shPath(), []string{"-c", command}
	}
	out, err := runRawCombined(cctx, s.root, s.scrubEnv(), 60*time.Second, bin, sargs...)
	res := clampStr(out, 12000)
	if err != nil {
		return res + "\n[exit: " + err.Error() + "]", nil
	}
	if res == "" {
		res = "(пустой вывод)"
	}
	return res, nil
}

// copyRec — рекурсивное копирование файла/директории.
func copyRec(src, dst string) error {
	info, err := os.Stat(src)
	if err != nil {
		return err
	}
	if info.IsDir() {
		if err := os.MkdirAll(dst, 0o755); err != nil {
			return err
		}
		entries, err := os.ReadDir(src)
		if err != nil {
			return err
		}
		for _, e := range entries {
			if err := copyRec(filepath.Join(src, e.Name()), filepath.Join(dst, e.Name())); err != nil {
				return err
			}
		}
		return nil
	}
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	os.MkdirAll(filepath.Dir(dst), 0o755)
	return os.WriteFile(dst, data, 0o644)
}

// contained проверяет, что path лежит внутри base (защита от ../).
func contained(base, path string) bool {
	rel, err := filepath.Rel(base, path)
	return err == nil && rel != ".." && !strings.HasPrefix(rel, "../")
}

// Push — copy-to-sandbox: файл/папка из рабочей директории в sandbox-root.
func (s *LocalSandbox) Push(srcRel string) (string, error) {
	src := resolvePath(s.workdir, srcRel)
	if !contained(s.workdir, src) {
		return "", errors.New("путь вне рабочей директории")
	}
	dst := filepath.Join(s.root, "data", filepath.Base(src))
	if err := copyRec(src, dst); err != nil {
		return "", err
	}
	return "OK: " + src + " → " + dst, nil
}

// Pull — copy-from-sandbox: файл/папка из sandbox-root в рабочую директорию.
func (s *LocalSandbox) Pull(srcRel, dstRel string) (string, error) {
	src := resolvePath(s.root, srcRel)
	if !contained(s.root, src) {
		return "", errors.New("путь вне сандбокса")
	}
	if dstRel == "" {
		dstRel = filepath.Base(src)
	}
	dst := resolvePath(s.workdir, dstRel)
	if !contained(s.workdir, dst) {
		return "", errors.New("назначение вне рабочей директории")
	}
	if err := copyRec(src, dst); err != nil {
		return "", err
	}
	return "OK: " + src + " → " + dst, nil
}

// sandboxTools — тулы сандбокса (регистрируются в BuildTools).
func sandboxTools(workdir string) []Tool {
	sb := NewLocalSandbox(workdir)
	return []Tool{
		{
			Spec: makeSpec("sandbox_run",
				"Выполнить shell-команду в изолированном userspace-сандбоксе (без рута: урезанный PATH, очищенный env, рабочая директория — sandbox-root). Безопаснее run_shell для недоверенного кода.",
				map[string]any{"command": pStr("команда")}, []string{"command"}),
			Handler: func(ctx context.Context, args map[string]any) (string, error) {
				cmd := strArg(args, "command")
				if cmd == "" {
					return "", errors.New("пустая команда")
				}
				return sb.Run(ctx, cmd)
			},
		},
		{
			Spec: makeSpec("sandbox_push",
				"copy-to-sandbox: скопировать файл/папку из рабочей директории в сандбокс (sandbox-root/data/).",
				map[string]any{"path": pStr("путь в рабочей директории")}, []string{"path"}),
			Handler: func(ctx context.Context, args map[string]any) (string, error) {
				return sb.Push(strArg(args, "path"))
			},
		},
		{
			Spec: makeSpec("sandbox_pull",
				"copy-from-sandbox: скопировать файл/папку из сандбокса в рабочую директорию.",
				map[string]any{
					"path": pStr("путь внутри сандбокса (например data/result.txt)"),
					"dest": pStr("куда сохранить в рабочей директории (по умолчанию — имя файла)"),
				}, []string{"path"}),
			Handler: func(ctx context.Context, args map[string]any) (string, error) {
				return sb.Pull(strArg(args, "path"), strArg(args, "dest"))
			},
		},
	}
}

// ---------- 13.7 Telegram-бот (long polling, только stdlib) ----------
// Токен: TELEGRAM_BOT_TOKEN или telegram_token в config.json.
// Режим демона: ./gomni -telegram — бот крутится бесконечно с backoff'ом,
// panic-recover на каждое сообщение и отдельным агентом на каждый чат.

type tgMessage struct {
	MessageID int64  `json:"message_id"`
	Text      string `json:"text"`
	Chat      struct {
		ID int64 `json:"id"`
	} `json:"chat"`
	From struct {
		FirstName string `json:"first_name"`
	} `json:"from"`
}

type tgUpdate struct {
	UpdateID int64      `json:"update_id"`
	Message  *tgMessage `json:"message"`
}

type TGBot struct {
	Token   string
	Offset  int64
	Running bool
	LLM     *LLMClient
	Workdir string
	Plugins []*Plugin
	Agents  map[int64]*Agent
	Mu      sync.Mutex
	stopCh  chan struct{}
	Logf    func(format string, args ...any)
}

func (b *TGBot) log(format string, args ...any) {
	if b.Logf != nil {
		b.Logf(format, args...)
	}
}

func (b *TGBot) api(method string, payload map[string]any, timeout time.Duration) (json.RawMessage, error) {
	body, _ := json.Marshal(payload)
	req, err := http.NewRequest("POST", "https://api.telegram.org/bot"+b.Token+"/"+method, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	client := &http.Client{Timeout: timeout, Transport: sharedHTTPTransport}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	var out struct {
		OK          bool            `json:"ok"`
		Result      json.RawMessage `json:"result"`
		Description string          `json:"description"`
	}
	if err := json.Unmarshal(data, &out); err != nil {
		return nil, err
	}
	if !out.OK {
		return nil, errors.New("telegram: " + out.Description)
	}
	return out.Result, nil
}

func (b *TGBot) sendMessage(chatID int64, text string) {
	if text == "" {
		text = "(пустой ответ)"
	}
	runes := []rune(text)
	for len(runes) > 0 {
		n := 3900
		if len(runes) < n {
			n = len(runes)
		}
		chunk := string(runes[:n])
		runes = runes[n:]
		if _, err := b.api("sendMessage", map[string]any{"chat_id": chatID, "text": chunk}, 30*time.Second); err != nil {
			b.log("tg send: %v", err)
			return
		}
	}
}

func (b *TGBot) agentFor(chatID int64) *Agent {
	b.Mu.Lock()
	defer b.Mu.Unlock()
	a, ok := b.Agents[chatID]
	if !ok {
		a = NewAgent(b.LLM, b.Workdir, b.Plugins...)
		a.StreamUI = false
		b.Agents[chatID] = a
	}
	return a
}

func (b *TGBot) handle(ctx context.Context, upd tgUpdate) {
	defer func() { // одно плохое сообщение не должно ронять бота
		if r := recover(); r != nil {
			b.log("tg panic: %v", r)
		}
	}()
	msg := upd.Message
	if msg == nil || strings.TrimSpace(msg.Text) == "" {
		return
	}
	b.log("tg ← %s: %s", msg.From.FirstName, trunc(msg.Text, 80))
	if strings.HasPrefix(msg.Text, "/start") || strings.HasPrefix(msg.Text, "/help") {
		b.registerCommands()
		b.sendMessage(msg.Chat.ID, `👋 Я Synergy Harness-агент. Пиши задачу — сам поищу в сети, посчитаю, поработаю с файлами.

Команды:
/reset — очистить контекст
/compact — сжать контекст
/search <запрос> — быстрый поиск
/model — текущая модель
/stats — статистика
/plugins — плагины
Сниппеты: !! <cmd> — выполнить shell, = <expr> — калькулятор.`)
		return
	}
	if strings.HasPrefix(msg.Text, "/reset") {
		b.Mu.Lock()
		delete(b.Agents, msg.Chat.ID)
		b.Mu.Unlock()
		b.sendMessage(msg.Chat.ID, "✓ Контекст очищен.")
		return
	}
	// ---- сниппеты: быстрые команды без LLM ----
	if strings.HasPrefix(msg.Text, "/search ") {
		res, err := WebSearch(ctx, strings.TrimPrefix(msg.Text, "/search "), 5)
		if err != nil {
			b.sendMessage(msg.Chat.ID, "⚠ "+err.Error())
			return
		}
		var sb strings.Builder
		for i, r := range res {
			fmt.Fprintf(&sb, "%d. %s\n%s\n%s\n\n", i+1, r.Title, r.URL, r.Snippet)
		}
		b.sendMessage(msg.Chat.ID, sb.String())
		return
	}
	if strings.HasPrefix(msg.Text, "!! ") { // shell-сниппет
		out, _ := NewLocalSandbox(b.Workdir).Run(ctx, strings.TrimPrefix(msg.Text, "!! "))
		b.sendMessage(msg.Chat.ID, "$ "+msg.Text[3:]+"\n"+out)
		return
	}
	if strings.HasPrefix(msg.Text, "= ") { // калькулятор-сниппет
		v, err := evalExpr(strings.TrimPrefix(msg.Text, "= "))
		if err != nil {
			b.sendMessage(msg.Chat.ID, "⚠ "+err.Error())
		} else {
			b.sendMessage(msg.Chat.ID, "= "+strconv.FormatFloat(v, 'g', 12, 64))
		}
		return
	}
	switch strings.TrimSpace(msg.Text) {
	case "/compact":
		a := b.agentFor(msg.Chat.ID)
		if m, err := a.compactContext(ctx); err != nil {
			b.sendMessage(msg.Chat.ID, "⚠ "+err.Error())
		} else {
			b.sendMessage(msg.Chat.ID, "✓ "+m)
		}
		return
	case "/model":
		b.sendMessage(msg.Chat.ID, "🧠 "+b.LLM.Model+" @ "+b.LLM.BaseURL)
		return
	case "/stats":
		a := b.agentFor(msg.Chat.ID)
		b.sendMessage(msg.Chat.ID, fmt.Sprintf("📊 сообщений: %d, контекст: ~%d KB, токенов: %d", len(a.Messages), a.contextSize()/1024, a.TotalTok))
		return
	case "/plugins":
		if len(b.Plugins) == 0 {
			b.sendMessage(msg.Chat.ID, "(плагинов нет)")
			return
		}
		var sb strings.Builder
		for _, p := range b.Plugins {
			fmt.Fprintf(&sb, "• %s v%s (%d тулов)\n", p.Name, p.Version, len(p.Tools))
		}
		b.sendMessage(msg.Chat.ID, sb.String())
		return
	}
	b.api("sendChatAction", map[string]any{"chat_id": msg.Chat.ID, "action": "typing"}, 10*time.Second)
	ans, err := b.agentFor(msg.Chat.ID).Run(ctx, msg.Text)
	if err != nil {
		ans = "⚠ " + err.Error()
	}
	b.sendMessage(msg.Chat.ID, ans)
}

// registerCommands — нативное меню-кнопка "/" в клиенте Telegram.
func (b *TGBot) registerCommands() {
	cmds := []map[string]string{
		{"command": "start", "description": "приветствие и справка"},
		{"command": "reset", "description": "очистить контекст"},
		{"command": "compact", "description": "сжать контекст"},
		{"command": "search", "description": "быстрый веб-поиск"},
		{"command": "model", "description": "текущая модель"},
		{"command": "stats", "description": "статистика"},
		{"command": "plugins", "description": "плагины"},
	}
	if _, err := b.api("setMyCommands", map[string]any{"commands": cmds}, 15*time.Second); err != nil {
		b.log("setMyCommands: %v", err)
	}
}

// RunForever — бесконечный цикл с экспоненциальным backoff (дизайн под 20+ часов аптайма).
func (b *TGBot) RunForever(ctx context.Context) {
	b.Running = true
	b.stopCh = make(chan struct{})
	backoff := time.Second
	for {
		select {
		case <-b.stopCh:
			b.Running = false
			return
		case <-ctx.Done():
			b.Running = false
			return
		default:
		}
		raw, err := b.api("getUpdates", map[string]any{"offset": b.Offset, "timeout": 25}, 40*time.Second)
		if err != nil {
			b.log("tg poll: %v (retry через %s)", err, backoff)
			time.Sleep(backoff)
			if backoff < 30*time.Second {
				backoff *= 2
			}
			continue
		}
		backoff = time.Second
		var updates []tgUpdate
		if json.Unmarshal(raw, &updates) != nil {
			continue
		}
		for _, upd := range updates {
			b.Offset = upd.UpdateID + 1
			go b.handle(ctx, upd)
		}
	}
}

func (b *TGBot) Stop() {
	if b.stopCh != nil {
		close(b.stopCh)
	}
}
